            aIngress ^= (RotL64(aHeartLaneA[((aIndex + 13683U)) & S_BLOCK1], 11U) ^ RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 10694U)) & S_BLOCK1], 23U));
